دالة بحث_ثنائي(ق, ع) {
    متغير أ = ٠
    متغير ب = طول(ق) - ١
    متغير م = -١
    طالما (أ <= ب) {
        متغير وسط = (أ + ب) // ٢
        إذا (ق[وسط] == ع) {
            م = وسط
            ارجع م
        } وإلا إذا (ق[وسط] < ع) {
            أ = وسط + ١
        } وإلا {
            ب = وسط - ١
        }
    }
    ارجع م
}
